// ============================================
// FIND ROW AND EXTRACT URLS
// ============================================

const webhookData = $('Trigger Validation').first().json;
const dayIndex = webhookData.body?.day_index || webhookData.day_index || 8;

const allRows = $input.all().map(item => item.json);
const targetRow = allRows.find(row => String(row.day_index) === String(dayIndex));

if (!targetRow) {
  throw new Error(`No row found with day_index = ${dayIndex}`);
}

// URL fields to validate
const urlFields = [
  { field: 'artist_portrait_url', titleField: null },
  { field: 'hero_url', titleField: 'hero_title' },
  { field: 'art2_url', titleField: 'art2_title' },
  { field: 'style_art_url', titleField: 'style_art_title' },
  { field: 'mini1_url', titleField: 'mini1_title' },
  { field: 'mini2_url', titleField: 'mini2_title' }
];

const urlsToCheck = [];
urlFields.forEach(({ field, titleField }) => {
  const url = targetRow[field];
  if (url && url.startsWith('http')) {
    urlsToCheck.push({
      field: field,
      url: url,
      title: titleField ? targetRow[titleField] : 'Artist Portrait',
      artistName: targetRow.artist_name,
      dayIndex: dayIndex
    });
  }
});

return urlsToCheck.map(item => ({ json: item }));

// ============================================
// COLLECT VALIDATION RESULTS
// ============================================

const results = $input.all();
const failedUrls = [];
const passedUrls = [];

results.forEach((result, idx) => {
  const originalData = $('Extract URLs').all()[idx]?.json || {};
  const statusCode = result.json.statusCode || result.json.status || 0;
  const error = result.json.error || null;

  const urlInfo = {
    field: originalData.field,
    url: originalData.url,
    title: originalData.title,
    artistName: originalData.artistName,
    dayIndex: originalData.dayIndex,
    statusCode: statusCode
  };

  if (error || statusCode < 200 || statusCode >= 400) {
    failedUrls.push(urlInfo);
  } else {
    passedUrls.push(urlInfo);
  }
});

const dayIndex = results[0]?.json?.dayIndex || $('Extract URLs').first().json.dayIndex;
const artistName = $('Extract URLs').first().json.artistName;

return {
  dayIndex: dayIndex,
  artistName: artistName,
  totalChecked: results.length,
  passed: passedUrls.length,
  failed: failedUrls.length,
  failedUrls: failedUrls,
  passedUrls: passedUrls,
  allValid: failedUrls.length === 0
};

// All URLs passed validation
const data = $input.first().json;
return {
  success: true,
  message: `✅ All ${data.totalChecked} URLs validated successfully for Day ${data.dayIndex}: ${data.artistName}`,
  details: data
};

// ============================================
// BUILD PROMPT TO FIX FAILED URLS
// ============================================

const data = $input.first().json;
const failedUrls = data.failedUrls;
const artistName = data.artistName;

let prompt = `You need to find replacement Wikimedia Commons image URLs for the following failed URLs.

Artist: ${artistName}

Failed URLs that need replacement:
`;

failedUrls.forEach((item, idx) => {
  prompt += `\n${idx + 1}. Field: ${item.field}\n`;
  prompt += `   Painting: ${item.title}\n`;
  prompt += `   Failed URL: ${item.url}\n`;
});

prompt += `\n\nFor each failed URL, provide a working Wikimedia Commons URL for the same painting or a similar famous work by ${artistName}.

RULES:
- Use ONLY Wikimedia Commons URLs starting with https://upload.wikimedia.org/wikipedia/commons/
- URLs must end with .jpg or .png
- Do NOT use Google Art Project URLs
- Each URL must be for a DIFFERENT painting

Respond in this EXACT format (one line per replacement):
field_name|new_url

Example:
hero_url|https://upload.wikimedia.org/wikipedia/commons/example.jpg

Provide ONLY the replacements, no other text.`;

return {
  prompt: prompt,
  failedUrls: failedUrls,
  dayIndex: data.dayIndex,
  artistName: artistName
};

// ============================================
// PARSE REPLACEMENT URLS
// ============================================

const prevData = $('Build Fix Prompt').first().json;
const rawResponse = $input.first().json.message?.content || $input.first().json.text || '';

let response = rawResponse;
if (Array.isArray(rawResponse)) {
  response = rawResponse.map(item => item.text || '').join('');
}

const lines = response.trim().split('\n').filter(l => l.includes('|'));
const replacements = {};

lines.forEach(line => {
  const parts = line.split('|');
  if (parts.length >= 2) {
    const field = parts[0].trim();
    const url = parts[1].trim();
    if (url.startsWith('http')) {
      replacements[field] = url;
    }
  }
});

return {
  replacements: replacements,
  dayIndex: prevData.dayIndex,
  artistName: prevData.artistName,
  failedCount: prevData.failedUrls.length,
  fixedCount: Object.keys(replacements).length
};

// Final response with fix summary
const data = $('Parse Replacements').first().json;
return {
  success: true,
  message: `🔧 Fixed ${data.fixedCount} of ${data.failedCount} failed URLs for Day ${data.dayIndex}: ${data.artistName}`,
  replacements: data.replacements
};
